#!/usr/bin/env bash
# Rebuilds wasm.ts (the lossless JPEG repack module) from pinned sources.
#
#   EMSDK=/path/to/emsdk ./build.sh [workdir]
#
# Needs: emsdk with Emscripten 6.0.13 activated in $EMSDK, cmake >= 3.10, curl, sha256sum,
# base64, node. Downloads the libjpeg-turbo 3.1.4.1 release tarball (checked against its
# SHA-256 below), builds only the static libjpeg (no SIMD, no arithmetic coding, no tools,
# getenv disabled), links repack.c into a standalone wasm with no JavaScript glue, and
# writes wasm.ts next to this script. The build is reproducible: the same inputs give the
# same wasm bytes (SHA-256 in README.md and wasm.ts).
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
work="${1:-$(mktemp -d)}"
version=3.1.4.1
tarball_sha=ecae8008e2cc9ade2f2c1bb9d5e6d4fb73e7c433866a056bd82980741571a022
url="https://github.com/libjpeg-turbo/libjpeg-turbo/releases/download/${version}/libjpeg-turbo-${version}.tar.gz"

: "${EMSDK:?set EMSDK to an emsdk checkout with 6.0.13 activated}"
# shellcheck disable=SC1091
source "$EMSDK/emsdk_env.sh" >/dev/null 2>&1
emcc --version | head -1 | grep -q ' 6\.0\.13 ' || { echo "need Emscripten 6.0.13" >&2; exit 1; }

mkdir -p "$work"
cd "$work"
if [ ! -f "libjpeg-turbo-${version}.tar.gz" ]; then curl -sSfL -o "libjpeg-turbo-${version}.tar.gz" "$url"; fi
echo "${tarball_sha}  libjpeg-turbo-${version}.tar.gz" | sha256sum -c -
rm -rf src build && mkdir src build
tar -xzf "libjpeg-turbo-${version}.tar.gz" -C src --strip-components=1

flags="-Oz -flto -DNO_GETENV -ffile-prefix-map=$work=."
(cd build && emcmake cmake ../src -DCMAKE_BUILD_TYPE=MinSizeRel -DCMAKE_C_FLAGS_MINSIZEREL="$flags" \
	-DWITH_SIMD=0 -DENABLE_SHARED=0 -DWITH_TURBOJPEG=0 -DWITH_ARITH_DEC=0 -DWITH_ARITH_ENC=0 \
	-DWITH_TOOLS=0 -DWITH_TESTS=0 -DCMAKE_POSITION_INDEPENDENT_CODE=0 >cmake.log \
	&& emmake make -j4 jpeg-static >make.log)

emcc $flags -I src/src -I build "$here/repack.c" build/libjpeg.a -o repack.wasm \
	-sSTANDALONE_WASM=1 --no-entry -sFILESYSTEM=0 -sMALLOC=emmalloc \
	-sALLOW_MEMORY_GROWTH=1 -sINITIAL_MEMORY=2MB -sMAXIMUM_MEMORY=1GB -sSTACK_SIZE=128KB \
	-sEXPORTED_FUNCTIONS=_jr_repack,_jr_verify,_jr_out_ptr,_jr_out_len,_jr_out_free,_jr_malloc,_jr_free,_jr_last_error,_jr_test_tamper

sha=$(sha256sum repack.wasm | cut -d' ' -f1)
size=$(stat -c %s repack.wasm)
node -e '
const fs = require("fs");
const [wasm, out, sha, size] = process.argv.slice(1);
const b64 = fs.readFileSync(wasm).toString("base64");
fs.writeFileSync(out, `/**
 * Lossless JPEG repack (libjpeg-turbo 3.1.4.1 + repack.c) compiled to WebAssembly,
 * ${size} bytes, base64 below. Generated by build.sh in this folder (sources, versions and
 * licences in README.md); do not edit by hand. Loaded by ../../jpeg-repack.ts.
 */
export const JPEG_REPACK_WASM_SHA256 = "${sha}";
export default "${b64}";
`);
' repack.wasm "$here/wasm.ts" "$sha" "$size"
echo "repack.wasm: $size bytes, sha256 $sha"
gzip -9 -c repack.wasm | wc -c | sed 's/^/gzip -9: /'
if command -v brotli >/dev/null; then brotli -c -q 11 repack.wasm | wc -c | sed 's/^/brotli -q 11: /'; fi
